SELECT F0_0.C_NAME AS C_NAME, F0_0.C_CUSTKEY AS C_CUSTKEY, F0_0.O_ORDERKEY AS O_ORDERKEY, F0_0.O_ORDERDATE AS O_ORDERDATE, F0_0.O_TOTALPRICE AS O_TOTALPRICE, F0_0."SUM(L_QUANTITY)" AS "SUM(L_QUANTITY)", F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_0."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER", DENSE_RANK() OVER ( ORDER BY F0_0.O_TOTALPRICE DESC NULLS LAST, F0_0.O_ORDERDATE ASC NULLS LAST, F0_0._RESULT_TID) AS _RESULT_TID, F0_0._SETPROV_DUP_COUNT AS _SETPROV_DUP_COUNT
FROM (
SELECT F0_0."GROUP_0" AS C_NAME, F0_0."GROUP_1" AS C_CUSTKEY, F0_0."GROUP_2" AS O_ORDERKEY, F0_0."GROUP_3" AS O_ORDERDATE, F0_0."GROUP_4" AS O_TOTALPRICE, F0_0."AGGR_0" AS "SUM(L_QUANTITY)", F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_0."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER", F0_0._RESULT_TID AS _RESULT_TID, F0_0._SETPROV_DUP_COUNT AS _SETPROV_DUP_COUNT
FROM (SELECT * FROM temp_view_1) F0_0
ORDER BY O_TOTALPRICE DESC NULLS LAST, O_ORDERDATE ASC NULLS LAST) F0_0) F0_0
WHERE (F0_0._RESULT_TID <= 100))
SELECT F0_0.PROV_CUSTOMER_C__CUSTKEY AS PROV_CUSTOMER_C__CUSTKEY, F0_0.PROV_LINEITEM_L__ORDERKEY AS PROV_LINEITEM_L__ORDERKEY, F0_0.PROV_LINEITEM_L__LINENUMBER AS PROV_LINEITEM_L__LINENUMBER, F0_0.PROV_ORDERS_O__ORDERKEY AS PROV_ORDERS_O__ORDERKEY, F0_0."PROV_LINEITEM_1_L__ORDERKEY" AS "PROV_LINEITEM_1_L__ORDERKEY", F0_0."PROV_LINEITEM_1_L__LINENUMBER" AS "PROV_LINEITEM_1_L__LINENUMBER"
FROM (SELECT * FROM temp_view_0) F0_0;


